```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_cloudwatch_log_group" "example_com" {
  name = "aws_route53_example_com"
  retention_in_days = 30
  tags = {
    Environment = "Production"
  }
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  policy_name = "route53_query_logging_policy"
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.example_com.arn
      }
    ]
  })
}

resource "aws_route53_zone" "primary" {
  name = "primary.example.com"
  comment = "Primary Route 53 zone"
  tags = {
    Environment = "Production"
  }
}

resource "aws_cloudwatch_log_stream" "example_com_stream" {
  log_group_name = aws_cloudwatch_log_group.example_com.arn
  name = "aws_route53_example_com_stream"
}

resource "aws_route53_query_logging_config" "route53_query_logging_config" {
  log_group_arn = aws_cloudwatch_log_group.example_com.arn
  hosted_zone_id = aws_route53_zone.primary.zone_id
}
