provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "codebuild_role_example" {
  name = "codebuild_role_example"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_policy_example" {
  name = "codebuild_policy_example"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_codebuild_project" "codebuild_project_example" {
  name = "codebuild_project_example"
  service_role = aws_iam_role.codebuild_role_example.arn

  badge_enabled = true
  build_timeout = 60
  concurrent_build_limit = 1
  description = "Example CodeBuild project"
  encryption_key = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  project_visibility = "PUBLIC"
  queued_timeout = 300
  resource_access_role = aws_iam_role.codebuild_role_example.arn
  source_version = "master"
  tags = {
    Environment = "Development"
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  build_batch_config {
    service_role = aws_iam_role.codebuild_role_example.arn
    combine_artifacts = false
    timeout_in_mins = 60
  }

  cache {
    location = "s3://my-codebuild-cache-bucket"
    modes = ["LOCAL_SOURCE", "LOCAL_CACHE"]
    type = "S3"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/standard:5.0"
    type = "LINUX_CONTAINER"
  }

  file_system_locations {
    identifier = "efs"
    location = "fs-12345678"
    mount_options = "defaults"
    mount_point = "/mnt/efs"
    type = "EFS"
  }

  logs_config {
    cloudwatch_logs {
      group_name = "codebuild-logs"
      stream_name = "{project-name}"
    }
  }

  secondary_artifacts {
    artifact_identifier = "secondary-artifact"
    type = "CODEPIPELINE"
  }

  secondary_source_version {
    source_identifier = "github"
    source_version = "master"
  }

  secondary_sources {
    source_identifier = "github"
    type = "GITHUB"
    buildspec = "buildspec.yml"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/example/repo.git"
    report_build_status = true
  }

  source {
    type = "GITHUB"
    buildspec = "buildspec.yml"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/example/repo.git"
    report_build_status = true
  }

  vpc_config {
    security_group_ids = ["sg-12345678"]
    subnets = ["subnet-12345678", "subnet-23456789"]
    vpc_id = "vpc-12345678"
  }
}
```

