      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "eks_cluster_1_policy_attachment" {
  name       = "eks_cluster_1_policy_attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"

  roles = [aws_iam_role.eks_cluster_1.name]
}

resource "aws_vpc" "eks_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "eks_private_subnet_1" {
  vpc_id            = aws_vpc.eks_vpc.id
  cidr_block         = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "eks_public_subnet_1" {
  vpc_id            = aws_vpc.eks_vpc.id
  cidr_block         = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_1.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.eks_private_subnet_1.id,
      aws_subnet.eks_public_subnet_1.id,
    ]
  }

  version = var.version
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`. You can change this to any valid AWS region.
- **IAM Role**: An IAM role named `eks_cluster_1` is created with an assume role policy that allows the `eks.amazonaws.com` service to assume the role.
- **IAM Policy Attachment**: The `AmazonEKSClusterPolicy` IAM policy is attached to the IAM role.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Subnets**: Two subnets are created within the VPC: one private (`10.0.1.0/24`) and one public (`10.0.2.0/24`). These subnets are placed in different Availability Zones (`us-west-2a` and `us-west-2b`).
- **EKS Cluster**: An EKS cluster named based on the `cluster_name` variable and using the specified `version` is created. The cluster is associated with the IAM role and uses the VPC and subnets defined above.

