    r.type == "aws_iam_role_policy_attachment"
    r.expressions.policy_arn.constant_value == "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
    r.expressions.role.references[_] == "aws_iam_role.demo.name"
