  bucket = "example-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  tags = {
    Name = "Example Bucket"
  }
}

resource "aws_cloudwatch_metric_alarm" "example_metric_alarm" {
  alarm_name          = "ExampleMetricAlarm"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods = 3
  threshold           = 100
  period             = 60
  statistic          = "Average"
  namespace          = "AWS/S3"
  metric_name        = "BucketSizeBytes"
  dimensions         = {
    Bucket = aws_s3_bucket.example.bucket
  }

  alarm_description = "This alarm checks if the S3 bucket size exceeds 100MB."
  alarm_actions     = [aws_s3_bucket.example.arn]
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-west-2` region.
- **S3 Bucket**: An S3 bucket named `example-bucket-${random_string.random_suffix.result}` is created. The `random_string` resource generates a random suffix to ensure uniqueness.
- **CloudWatch Metric Alarm**: A metric alarm named `ExampleMetricAlarm` is set up to monitor the `BucketSizeBytes` metric of the S3 bucket. It triggers if the average size exceeds 100MB over 3 evaluation periods, with a period of 60 seconds. The alarm sends notifications to the S3 bucket's ARN.

