  function_name = "database_call_reducer"
  role          = aws_iam_role.lambda_execution_role.arn

  runtime     = "python3.8"
  handler     = "app.lambda_handler"
  code        = filebase64("path/to/database_call_reducer.zip")

  timeout     = 30
  memory_size = 128

