    prevent_destroy = true
  }

  cors_rule {
    allowed_methods   = ["GET", "PUT"]
    allowed_origins  = ["*"]
    allowed_headers  = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 300
  }

