```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "dynamodb_table_encryption_key" {
  description = "KMS key for DynamoDB encryption"
}

resource "aws_iam_role" "dynamodb_table_encryption_role" {
  name = "dynamodb_table_encryption_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })

  policies = [
    jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "kms:Encrypt",
            "kms:Decrypt",
            "kms:ReEncrypt*",
            "kms:GenerateDataKey*",
            "kms:DescribeKey"
          ]
          Effect = "Allow"
          Resource = aws_kms_key.dynamodb_table_encryption_key.arn
        }
      ]
    })
  ]
}

resource "aws_dynamodb_table" "my_dynamodb_table" {
  name = "my_dynamodb_table"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
    kms_key_arn = aws_kms_key.dynamodb_table_encryption_key.arn
  }

  tags = {
    Name = "My DynamoDB Table"
  }
}
```

