```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_group" "example_iam_group" {
  name = "ExampleIAMGroup"
}

resource "aws_iam_user" "example_iam_user" {
  name = "ExampleIAMUser"

  # Add the user to the group
  groups = [aws_iam_group.example_iam_group.name]
}

resource "aws_iam_policy" "example_iam_policy" {
  name        = "ExampleIAMPolicy"
  description = "Example IAM policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "example_iam_role" {
  name = "ExampleIAMRole"

  # Attach the policy to the role
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  # Attach the policy to the role
  managed_policy_arns = [aws_iam_policy.example_iam_policy.arn]

  # Assign the role to the user
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_user.example_iam_user.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}
```

