resource "aws_iam_role_policy_attachment" "codebuild_service_role_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRolePolicy"
}

resource "aws_codebuild_project" "cs_class_autograder" {
  name             = "cs-class-autograder"
  service_role     = aws_iam_role.codebuild_service_role.arn
  badge_enabled    = true
  build_timeout    = 60
  concurrent_build_limit = 1
  description     = "Autograder for CS class"
  encryption_key   = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  source_version   = "master"
  tags            = {
    Name = "cs-class-autograder"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image         = "aws/codebuild/standard:5.0"
    type         = "LINUX_CONTAINER"
  }

  logs_config {
    cloudwatch_logs {
      log_group_name = "/aws/codebuild/cs-class-autograder"
    }
  }

  secondary_sources {
    source_identifier = "github-source"
    type              = "GITHUB"
    location          = "https://github.com/example/cs-class.git"
    report_build_status = true
  }

  secondary_source_versions {
    source_identifier = "github-source"
    source_version   = "master"
  }
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "cs-class-autograder-results"
  acl    = "private"
  tags = {
    Name = "cs-class-autograder-results"
  }
}

resource "aws_s3_bucket_policy" "autograder_results_bucket_policy" {
  bucket = aws_s3_bucket.autograder_results_bucket.bucket

