}

resource "aws_s3_bucket_policy" "student_code_bucket_policy" {
  bucket = aws_s3_bucket.student_code_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Principal = "*"
        Action = "s3:*"
        Resource = "${aws_s3_bucket.student_code_bucket.arn}/*"
        Condition = {
          StringNotEquals = {
            "aws:SourceIp" = "0.0.0.0/0"
          }
        }
      }
    ]
  })
}

