provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-1234567890"
  acl    = "private"

  tags = {
    Name = "Cat Pictures Bucket"
  }
}

resource "aws_s3_bucket_policy" "cat_pictures_bucket_policy" {
  bucket = aws_s3_bucket.cat_pictures_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name = "Cat Pictures API"

  tags = {
    Name = "Cat Pictures API"
  }
}

resource "aws_api_gateway_resource" "cat_pictures_api_root" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  path_part   = "/"
}

resource "aws_api_gateway_method" "cat_pictures_api_get" {
  rest_api_id     = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id     = aws_api_gateway_resource.cat_pictures_api_root.id
  http_method    = "GET"
  authorization  = "NONE"
  api_key_required = false
}

resource "aws_api_gateway_integration" "cat_pictures_api_get_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.cat_pictures_api_root.id
  http_method            = "GET"
  type                   = "AWS_PROXY"
  uri                    = "arn:aws:apigateway:${var.aws_region}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_pictures_lambda.arn}/invocations"
  integration_http_method = "POST"
  passthrough_behavior = "WHEN_NO_MATCH"
}

resource "aws_lambda_function" "cat_pictures_lambda" {
  function_name = "cat-pictures-lambda-1234567890"
  role           = aws_iam_role.cat_pictures_lambda_role.arn

  runtime       = "nodejs14.x"
  handler       = "index.handler"
  code         = filebase64("path/to/cat-pictures-lambda.zip")
  memory_size   = 128
  timeout       = 30

  environment = {
    Variables = {
      CAT_PICTURES_BUCKET = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_iam_role" "cat_pictures_lambda_role" {
  name = "cat-pictures-lambda-role-1234567890"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cat_pictures_lambda_policy_attachment" {
  role       = aws_iam_role.cat_pictures_lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_api_gateway_deployment" "cat_pictures_api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
}

resource "aws_api_gateway_stage" "cat_pictures_api_stage" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
  variables   = {
    CAT_PICTURES_BUCKET = aws_s3_bucket.cat_pictures_bucket.bucket
  }
}
