provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = "cat_pictures_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  range_key      = "timestamp"
  read_capacity  = 5
  write_capacity = 5
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket        = "cat-pictures-bucket-${random_string.random_suffix.result}"
  acl           = "private"
  force_destroy = true
  tags = {
    Name = "Cat Pictures Bucket"
  }
}

resource "aws_lambda_function" "cat_picture_upload_handler" {
  function_name = "cat_picture_upload_handler"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  timeout       = 30
  memory_size   = 128

  code {
    s3_bucket = aws_s3_bucket.cat_pictures_bucket.bucket
    s3_key    = "lambda/cat_picture_upload_handler.zip"
  }

  environment {
    variables = {
      TABLE_NAME = aws_dynamodb_table.cat_pictures_table.name
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  vpc_config {
    subnet_ids     = [aws_subnet.subnet.id]
    security_group_ids = [aws_security_group.lambda_sg.id]
  }

  depends_on = [aws_dynamodb_table.cat_pictures_table, aws_s3_bucket.cat_pictures_bucket]
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_permission" "cat_picture_upload_permission" {
  action       = "s3:PutObject"
  function_name = aws_lambda_function.cat_picture_upload_handler.function_name
  principal    = "s3.amazonaws.com"
  source_arn   = aws_s3_bucket.cat_pictures_bucket.arn
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name = "cat-pictures-api"
}

resource "aws_api_gateway_resource" "cat_pictures_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "cat-pictures"
}

resource "aws_api_gateway_method" "cat_picture_get_method" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id = aws_api_gateway_resource.cat_pictures_resource.id
  http_method = "GET"
  authorization = "NONE"
  request_parameters = {
    "method.request.querystring.limit" = "true"
  }
  request_models = {
    "application/json" = "com.example.CatPicture"
  }
  request_validator_id = aws_api_gateway_request_validator.cat_picture_request_validator.id
}

resource "aws_api_gateway_request_validator" "cat_picture_request_validator" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  name        = "cat-picture-request-validator"
  validate_request_body = false
  validate_request_parameters = true
}

resource "aws_subnet" "subnet" {
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  vpc_id = aws_vpc.vpc.id
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda-sg"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
}
