  vpc_id = aws_vpc.main.id
  description = "Allow inbound PostgreSQL traffic"
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "DB Security Group"
  }
}

resource "aws_kms_key" "db_kms_key" {
  description = "KMS key for PostgreSQL encryption"
  tags = {
    Name = "DB KMS Key"
  }
}

resource "aws_db_parameter_group" "pg_param_group" {
  family = "postgres13"
  description = "Custom parameter group for PostgreSQL settings"
  parameters = {
    max_connections = "100"
    work_mem = "128MB"
  }
  tags = {
    Name = "DB Parameter Group"
  }
}

resource "aws_db_instance" "db_instance" {
  instance_class = "t3.micro"
  allocated_storage = 20
  engine = "postgres"
  engine_version = "13.6"
  db_name = "mydatabase"
  username = "admin"
  password = "securepassword123"
