  security_groups = [aws_security_group.db_sg.id]
  parameter_group_name = aws_db_parameter_group.pg_param_group.name
  kms_key_id = aws_kms_key.db_kms_key.id
  multi_az = true
  backup_retention_period = 7
  tags = {
    Name = "DB Instance"
  }
}
