provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "iam_role_pike" {
  name = "iam_role_pike"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "iam_role_policy_attachment_pike" {
  role       = aws_iam_role.iam_role_pike.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSServerlessReadOnlyAccess"
}

resource "aws_s3_bucket" "s3_bucket_pike" {
  bucket = "pike-s3-bucket-${random_string.random_suffix.id}"
  acl    = "private"

  tags = {
    Name = "pike-s3-bucket"
  }
}

resource "aws_s3_bucket_policy" "s3_bucket_policy_pike" {
  bucket = aws_s3_bucket.s3_bucket_pike.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Resource = "${aws_s3_bucket.s3_bucket_pike.arn}/*"
      }
    ]
  })
}

resource "aws_rds_option_group" "option_group_pike" {
  name           = "option-group-pike"
  major_engine_version = "11"
  engine         = "sqlserver-ee"

  option {
    name = "SQLSERVER_AUDIT"
    option_settings = jsonencode({
      "AuditFileLocation" = "s3://${aws_s3_bucket.s3_bucket_pike.bucket}/audit"
      "AuditRetentionPeriod" = 30
      "AuditCompressionType" = "GZIP"
      "AuditEncryptionEnabled" = true
      "AuditEncryptionKMSKeyId" = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
      "AuditLogDestinationType" = "S3"
      "AuditLogDestinationArn" = aws_s3_bucket.s3_bucket_pike.arn
      "AuditLogDestinationRoleArn" = aws_iam_role.iam_role_pike.arn
    })
  }

  option {
    name = "TDE"
    option_settings = jsonencode({
      "EncryptionMode" = "AES256"
      "KMSKeyId" = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
    })
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
  upper = false
  lower = true
  number = true
}
