  vpc_security_group_ids = [aws_security_group.lightsail_mysql_sg.id]
  subnet_id = aws_subnet.lightsail_mysql_subnet.id
}

resource "aws_security_group" "lightsail_mysql_sg" {
  name        = "lightsail-mysql-sg"
  description = "Security group for Lightsail MySQL instance"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Allow SSH access from anywhere
  }

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Allow MySQL access from anywhere
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

