  cidr_block = "10.0.0.0/16"
}

resource "aws_network_acl" "acl_main" {
  vpc_id = aws_vpc.vpc_main.id

  ingress_rule {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
